  if(EMBEDDED){if(!profilesReady)return;profileSaveQueue.current=profileSaveQueue.current.catch(()=>{}).then(()=>api('profiles',{profiles})).catch(()=>setToast({type:'error',message:'Profile konnten nicht gespeichert werden. Exportiere sie als Datei.'}));return;}
