  setBusy(true);
  if(!startupDetectionRef.current)startupDetectionRef.current=api('discover',{});
  startupDetectionRef.current.then(x=>{if(!alive)return;const list=x.devices.map(d=>({...d,category:categorize(d)}));setStatus(x.status);coverageStatusRef.current=coverageStatusSignature(x.status);setDevices(list);setPreview(false);setSelected(list.filter(d=>d.directMode).map(d=>d.id));setRunning(true);const active=x.status.active?.[0]?.settings;if(active){try{setConfig(validConfig(active));}catch{}}}).catch(e=>{if(alive)setStatus({connected:false,error:`RGB-Erkennung fehlgeschlagen: ${e.message}`});}).finally(()=>{if(alive){setBusy(false);void refreshCoverage();}});
