 async function applyNative(settings){if(writeBusy.current)return;setLiveEnabled(false);setBusy(true);writeBusy.current=true;try{const previous=await rememberBefore(settings.deviceIds||[]);const result=await api('native-effect',settings);storeRestore(previous);const [nextStatus,nextDevices]=await Promise.all([api('status'),api('devices')]);setStatus(nextStatus);setDevices(nextDevices.devices.map(d=>({...d,category:categorize(d)})));notify(`Herstellereffekt auf ${result.applied.length} Geräte angewendet.`);}catch(e){notify(e.message,'error');}finally{writeBusy.current=false;setBusy(false);void refreshCoverage();}}
 async function showControlWindow(){setBusy(true);try{await api('window/show',{});notify('RGB-Steuerfenster geöffnet. Windows-Geräte benötigen dieses Fenster im Vordergrund.');}catch(e){notify(e.message,'error');}finally{setBusy(false);}}
